union bpf_attr attr = {
    .map_type    = BPF_MAP_TYPE_HASH,
    .key_size    = sizeof(u32),
    .value_size  = sizeof(u64),
    .max_entries = 100,
    .map_flags   = 0,
};

int map_fd = bpf(
    BPF_MAP_CREATE,         // cmd
    &attr,                  // attr (Specific attributes for cmd)
    sizeof(attr)            // size
);

